def solve_shortest_path(distances: dict) -> int:
    """
    Finds the shortest total distance to visit all four families.

    Args:
        distances: A dictionary where keys are tuples representing connections between locations, and values are the distances between them.

    Returns:
        The shortest total distance to visit all four families.
    """

    # Define a helper function for Dijkstra's algorithm
    def dijkstra(start: str) -> dict:
      distances_from_start = {location: float('inf') for location in distances}
      distances_from_start[start] = 0
      visited = set()

      while len(visited) < len(distances):
        current_location = min((location for location in distances_from_start if location not in visited), key=lambda location: distances_from_start[location])
        visited.add(current_location)

        for neighbor, distance in distances.items():
          if neighbor == current_location and distance != 0:
            continue
          if distances_from_start[neighbor] > distances_from_start[current_location] + distance:
            distances_from_start[neighbor] = distances_from_start[current_location] + distance

      return distances_from_start

    # Calculate shortest distances from school M to all other locations
    shortest_distances_from_M = dijkstra('M')

    # Find the shortest path to visit all families starting from school M
    total_distance = shortest_distances_from_M['A'] + min(
        {shortest_distances_from_M[location] for location in ('B', 'C', 'D')}
    ) 

    return total_distance

