    """

    def is_valid_grid(grid: list[list[int]]) -> bool:
        """Checks if a given grid satisfies the condition that the sum of numbers in each row is 0."""
        for row in grid:
            if sum(row) != 0:
                return False
        return True

    def count_valid_grids() -> int:
        """Counts the number of valid 3x3 grids where the sum of numbers in each row is 0."""
        count = 0
        for i in range(3):
            for j in range(3):
                for k in range(3):
                    grid = [[i, j, k]]
                    if is_valid_grid(grid):
                        count += 1
        return count

    def count_valid_grids_with_zero_column_sum() -> int:
        """Counts the number of valid 3x3 grids where the sum of numbers in each row and column is 0."""
        count = 0
        for i in range(3):
            for j in range(3):
                for k in range(3):
                    grid = [[i, j, k]]
                    if is_valid_grid(grid) and sum([sum(col) for col in zip(*grid)]) == 0:
